import json
from pathlib import Path
from PIL import Image
R=Path(__file__).parent
M=json.loads((R/'source_map.json').read_text(encoding='utf-8'))
def src(a,b=None):
 b=a if b is None else b
 ps=[p for p in M['pages'] if p['printed'] and a<=p['printed']<=b]
 return {'pdf':[p['pdf'] for p in ps],'printed':[p['printed'] for p in ps]}
def p(t):return {'type':'p','text':t}
def bullets(*a):return {'type':'bullets','items':list(a)}
def steps(title,*a):return {'type':'steps','title':title,'items':list(a)}
def table(h,rows):return {'type':'table','headers':h,'rows':rows}
def formula(t,s,e):return {'type':'formula','text':t,'symbols':s,'explanation':e}
def chapter(n):
 c=M['chapters'][n-1]
 return {'id':f'O{n:02d}','order':n,'title':f"제{n}장. {c['title']}",'source':{'pdf':c['pdf'],'printed':c['printed']},'overview':[],'flow':[],'sections':[],'codes':[],'figures':[],'key_points':[],'comparisons':[],'review':[],'checklist':[],'index_terms':[],'coverage':[],'limitations':[],'verification':{'read_pdf_pages':c['pdf'],'visually_checked_pdf_pages':[],'notes':[]}}
def sec(c,num,title,a,b,*blocks):
 s={'number':num,'title':title,'source':src(a,b),'blocks':list(blocks)};c['sections'].append(s)
 c['coverage'].append({'number':num,'title':title,'source':src(a,b),'topics':[x.get('text',x.get('title',x['type']))[:130] for x in blocks]})
def code(c,title,a,txt,meaning,process,cautions=None,excerpt=False):
 i=f"{c['id']}-E{len(c['codes'])+1:02d}"
 c['codes'].append({'id':i,'title':title,'source':src(a),'code':txt,'excerpt':excerpt,'excerpt_note':'해당 원문 그림 또는 본문 코드에서 발췌하였다.' if excerpt else '', 'meaning':meaning,'process':process,'output':'원문에 실행 결과 미제시','cautions':cautions or []})
 c['verification']['visually_checked_pdf_pages']+=src(a)['pdf']
 return {'type':'code_ref','id':i}
def fig(c,title,a,rat,caption,meaning):
 i=f"{c['id']}-F{len(c['figures'])+1:02d}";source=src(a);pdf=source['pdf'][0]
 ip=R/'images'/f'{pdf:04d}.jpg';im=Image.open(ip);w,h=im.size;box=tuple(round(v*(w if k%2==0 else h)) for k,v in enumerate(rat))
 fp=R/'assets'/f'{i}.png';fp.parent.mkdir(exist_ok=True);im.crop(box).save(fp)
 c['figures'].append({'id':i,'title':title,'file':str(fp.resolve()),'source':source,'caption':caption,'meaning':meaning,'crop':{'image':str(ip.resolve()),'bbox':box}})
 c['verification']['visually_checked_pdf_pages']+=[pdf]
 return {'type':'figure_ref','id':i}
def finish(c,keys,reviews,checks,terms):
 c['key_points']=keys;c['review']=reviews
 c['checklist']=[{'text':t,'source':src(a,b)} for t,a,b in checks]
 c['index_terms']=[{'term':t,'section':s} for t,s in terms]
 c['verification']['visually_checked_pdf_pages']=sorted(set(c['verification']['visually_checked_pdf_pages']))
 c['verification']['notes']+=['제공된 전 본문·요약·연습 문제·추가 자료·참고문헌 페이지를 검토하였다. 외부 참고문헌 내용과 새 문제 풀이를 추가하지 않았다.','원문의 구현·제품·성능 설명은 원문이 기술하는 범위와 시점을 유지하였다.']
 (R/'chapters'/f"{c['order']:02d}.json").write_text(json.dumps(c,ensure_ascii=False,indent=2),encoding='utf-8')

c=chapter(6)
c['overview']=['공유 데이터에 병행하게 접근할 때 생기는 경쟁 조건과 임계구역 문제를 정의하고, 하드웨어 명령에서 mutex 락·세마포·모니터까지 동기화 수단을 살펴본다.','상호 배제를 제공하는 것과 실행의 진행을 보장하는 것은 함께 검토해야 한다. 교착 상태·우선순위 역전 및 경합 정도에 따른 성능 차이도 이 장의 범위이다.']
c['flow']=['경쟁 조건 → 임계구역의 세 요구 조건 → Peterson의 해결안과 명령 재정렬의 한계','메모리 장벽·원자적 명령·원자적 변수 → mutex·세마포 → 모니터와 조건 변수','라이브니스 실패 → 동기화 도구의 경합별 평가']
sec(c,'6.1','배경',283,285,
 p('**협력적 프로세스**는 시스템 안의 다른 프로세스 실행에 영향을 주거나 영향을 받는다. 논리 주소 공간을 직접 공유하거나 공유 메모리·메시지 전달로 데이터를 공유할 수 있다. 병행 실행에서는 어느 명령 지점에서도 인터럽트와 실행 전환이 일어날 수 있고, 병렬 실행에서는 여러 코어의 명령 흐름이 동시에 진행된다. 공유 데이터에 대한 접근을 질서 있게 조정하지 않으면 데이터의 일관성이 손상될 수 있다.'),
 p('원문의 유한 버퍼 예는 채워진 버퍼 수를 나타내는 정수 count를 추가한다. 생산자는 항목을 넣고 count를 증가시키며 소비자는 항목을 꺼내고 감소시킨다. 각 코드는 따로 실행하면 올바르지만 count++와 count--는 각각 읽기·레지스터 계산·저장으로 나뉠 수 있다. 초기 count가 5일 때 두 연산을 병행하면 4, 5, 6이 될 수 있지만 올바른 값은 5이다.'),
 steps('원문에서 count가 4가 되는 교차 실행','생산자가 count=5를 자신의 레지스터로 읽고 6으로 증가시킨다.','소비자가 아직 5인 count를 다른 레지스터로 읽고 4로 감소시킨다.','생산자가 6을 count에 저장한 뒤 소비자가 4를 저장한다. 실제 채워진 버퍼는 5개지만 count는 4이다.'),
 p('**경쟁 상황(race condition)**은 여러 프로세스가 같은 자료를 병행하게 접근·조작하고 최종 결과가 접근의 특정 순서에 의존하는 상황이다. 원문 예에서는 한순간에 하나의 프로세스만 count를 조작하도록 보장해야 하며, 이를 위해 프로세스 동기화가 필요하다.'))
sec(c,'6.2','임계구역 문제',286,288,
 p('**임계구역(critical section)**은 적어도 하나의 다른 프로세스와 공유하는 데이터를 접근·갱신하는 코드 영역이다. 한 프로세스가 그 영역을 수행하는 동안 다른 프로세스는 자신의 해당 임계구역에서 실행할 수 없어야 한다. 임계구역 문제는 협력적으로 데이터를 공유하는 프로세스의 활동을 동기화할 프로토콜을 설계하는 문제이다.'),
 steps('프로세스의 일반 구조','진입 구역(entry section)에서 임계구역 진입 허가를 요청한다.','임계구역에서 공유 데이터를 조작한다.','퇴출 구역(exit section)을 수행하고 나머지 구역(remainder section)을 실행한다.'),
 table(['요구 조건','정확한 의미'],[['상호 배제','한 프로세스가 임계구역을 실행하면 다른 프로세스는 그들의 임계구역을 실행할 수 없다.'],['진행','임계구역이 비어 있고 진입 희망자가 있다면 나머지 구역에서 실행 중이지 않은 프로세스들만 다음 진입자 결정에 참여하며, 결정을 무한정 연기할 수 없다.'],['한정된 대기','한 프로세스의 진입 요청 이후 허가될 때까지 다른 프로세스의 임계구역 진입 횟수에 한계가 있어야 한다.']]),
 p('각 프로세스가 0이 아닌 속도로 실행된다고 가정하지만 프로세스 사이의 상대 속도는 가정하지 않는다. 커널의 열린 파일 리스트, 다음 사용 가능한 PID, 메모리 할당·프로세스 리스트·인터럽트 자료구조도 경쟁 조건에 노출된다. 단일 코어에서 공유 변수를 수정하는 동안 인터럽트를 금지할 수 있지만, 다중 처리기에 이를 적용하면 모든 처리기로 전달하는 비용과 효율 저하, 클록 갱신의 영향을 고려해야 한다.'),
 table(['커널','선점과 특성'],[['비선점형','커널 모드에서 실행 중인 프로세스는 커널을 나가거나 봉쇄되거나 자발적으로 CPU를 양보할 때까지 계속 실행한다. 원문은 한순간 커널 실행자가 하나라는 관점에서 커널 자료구조의 경쟁 조건을 설명한다.'],['선점형','커널 모드에서도 선점을 허용하므로 공유 자료구조를 신중히 보호해야 한다. SMP에서는 여러 처리기의 프로세스가 커널 모드에 있을 수 있다. 더 민첩한 응답과 실시간 프로세스의 선점에 유리하다.']]))
pet=code(c,'Peterson의 해결안: 프로세스 Pᵢ의 구조',289,'while (true) {\n    flag[i] = true;\n    turn = j;\n    while (flag[j] && turn == j)\n        ;\n\n    /* critical section */\n\n    flag[i] = false;\n\n    /*remainder section */\n}', '두 프로세스가 진입 의사와 순번을 공유하여 임계구역 진입을 조정한다.', ['flag[i]를 true로 만들고 turn을 상대 j로 지정한다.','상대가 진입 의사를 갖고 상대 차례이면 대기한다.','임계구역을 마치면 flag[i]를 false로 바꾼다.'],['공유 선언은 int turn;과 boolean flag[2];이다.','이 예는 현대 컴퓨터에서 명령 재정렬 때문에 올바른 실행을 보장할 수 없다는 원문의 제한과 함께 읽어야 한다.'],True)
sec(c,'6.3','Peterson의 해결안',288,291,
 p('Peterson의 해결안은 임계구역과 나머지 구역을 번갈아 실행하는 **두 프로세스**에 한정된다. turn은 진입 순번, flag 배열은 각 프로세스가 진입할 준비가 되었는지를 나타낸다. 두 프로세스가 함께 들어가려 하면 turn에 대한 마지막 배정이 먼저 들어갈 프로세스를 결정한다.'),pet,
 p('원문의 증명은 두 프로세스가 동시에 임계구역에 있다면 flag가 모두 true여야 하지만 turn은 동시에 두 값을 가질 수 없다는 점으로 상호 배제를 보인다. 진입을 막는 것은 상대가 진입 의사가 있고 상대 차례인 경우뿐이다. 상대가 나가면 flag를 false로 바꾸고, 다시 들어가려 해도 turn을 넘겨주므로 기다리던 프로세스가 무한정 양보하지 않는다.'),
 p('**적용 한계:** 현대 컴파일러와 프로세서는 데이터 종속성이 없는 읽기·쓰기를 재정렬할 수 있다. 원문은 x와 flag를 공유하는 두 스레드에서 x=100보다 flag=true가 먼저 보이면 기대한 100 대신 0을 출력할 수 있음을 보인다. Peterson의 진입 구역 첫 두 배정 순서가 바뀌면 두 스레드가 동시에 임계구역에 있을 수 있다. 따라서 논리적 증명만으로 현대 구조의 실행까지 보장한다고 해석하면 안 된다.'))
sec(c,'6.4','동기화를 위한 하드웨어 지원',291,297,p('원문은 메모리 장벽, 원자적 하드웨어 명령, 원자적 변수를 제시한다. 이들은 직접 동기화에 쓰이거나 더 높은 수준 도구를 만드는 기본 구성요소가 된다.'))
sec(c,'6.4.1','메모리 장벽',292,293,
 p('**메모리 모델**은 컴퓨터 구조가 프로그램의 메모리 접근에 보장하는 사항을 뜻한다. 원문은 한 처리기의 변경 결과가 다른 모든 처리기에 즉시 보이는 강한 순서와 즉시 보이지 않는 약한 순서를 구별한다. 구조마다 모델이 다르므로 공유 메모리 다중 처리기의 가시성을 임의로 가정할 수 없다.'),
 p('**메모리 장벽(memory barrier, memory fence)** 명령이 실행되면 뒤의 적재·저장 전에 앞의 적재·저장이 완료되도록 한다. 저장된 변경이 다른 처리기에 보이도록 보장하여 재정렬의 문제를 다룬다. 원문의 x/flag 예에서는 읽는 쪽에서 flag 적재 뒤 x 적재 전에, 쓰는 쪽에서는 x 배정 뒤 flag 배정 전에 장벽을 둔다. 매우 낮은 수준의 연산이며 원문은 주로 커널 개발자의 특수 동기화 코드에 사용된다고 설명한다.'))
cas=code(c,'원자적 compare_and_swap()의 정의',294,'int compare_and_swap(int *value, int expected, int new_value) {\n    int temp = *value;\n\n    if (*value == expected)\n        *value = new_value;\n\n    return temp;\n}', '현재 값이 expected와 같을 때에만 new_value를 저장하며, 성공 여부와 관계없이 원래 값을 반환한다.',['원래 *value를 temp에 보관한다.','기댓값과 현재 값이 같으면 값을 바꾼다.','temp를 반환한다. 원문은 전체 명령을 원자적 단위로 가정한다.'],['동시에 실행된 CAS 명령들은 임의의 순서로 순차 실행된다.'],True)
sec(c,'6.4.2','하드웨어 명령어',293,296,
 p('원자적 명령은 검사·변경 또는 교환을 인터럽트되지 않는 하나의 단위로 수행한다. test_and_set()은 원래 값을 반환하면서 대상을 true로 설정한다. false로 초기화한 lock을 이에 사용하면 먼저 도착한 실행자만 진입하고 나갈 때 false로 바꿀 수 있다.'),cas,
 p('CAS 상호 배제 예에서 lock은 0으로 초기화되고 compare_and_swap(&lock, 0, 1)을 반복한다. 첫 성공자는 원래 값 0을 받아 임계구역에 들어가고 퇴출 시 lock=0으로 바꾼다. 그러나 단순 반복은 상호 배제를 만족해도 **한정된 대기를 만족하지 않는다**. 원문의 별도 알고리즘은 waiting 배열을 false, lock을 0으로 초기화하고 퇴출 시 대기자를 순환 탐색한다. 다음 대기자에게 진입을 넘겨 최대 n−1번만 양보하도록 한다.'),
 p('원문의 Intel x86 설명은 cmpxchg가 CAS를 구현하고 대상 피연산자가 갱신되는 동안 lock 접두어로 버스를 잠가 원자적 실행을 강제한다고 기술한다. 여기서는 이 설명을 다른 구조의 세부 동작으로 확장하지 않는다.'))
sec(c,'6.4.3','원자적 변수',296,297,
 p('**원자적 변수**는 정수·부울 같은 기본 자료형에 원자적 연산을 제공한다. CAS는 흔히 직접 사용되기보다 이런 도구의 기초가 된다. 원문의 증가 함수는 현재 값을 읽고 그 값이 유지되어 있을 때만 1 증가시키는 CAS를 시도하며 충돌하면 반복한다.'),
 p('한 변수의 갱신이 원자적이라는 사실만으로 전체 알고리즘의 경쟁 조건이 사라지지는 않는다. 유한 버퍼에서 count가 원자적이어도 두 소비자가 count>0을 기다리다가 생산자가 항목 하나만 추가했을 때 함께 대기를 빠져나올 수 있다. 원문은 원자적 변수를 주로 카운터·시퀀스 생성기 같은 공유 데이터 한 개의 갱신에 적합한 도구로 제한하여 설명한다.'))
sec(c,'6.5','Mutex Locks',297,299,
 p('**Mutex 락**은 임계구역 진입 전에 acquire()로 획득하고 나올 때 release()로 반환하는 도구이다. available이라는 불린 값이 사용 가능 여부를 나타낸다. 획득·반환 호출은 원자적이어야 하며 CAS로 구현할 수 있다.'),
 p('원문의 단순 구현은 사용 불가능한 동안 반복 검사하는 **바쁜 대기**를 한다. 이 유형을 스핀락이라고 부른다. 하나의 CPU 코어를 여러 프로세스가 나누는 환경에서는 다른 프로세스가 쓸 CPU 주기를 낭비한다. 반면 대기하면서 문맥 교환을 하지 않는 이점이 있어 다중 코어에서 임계구역이 짧을 때 유리할 수 있다.'),
 p('원문이 제시하는 짧은 기간의 기준은 락 유지 시간이 대기와 재개를 위한 **두 번의 문맥 교환 시간보다 짧은 경우**이다. 락을 얻으려다 봉쇄되면 경합, 즉시 얻을 수 있으면 비경합으로 본다. 많은 스레드가 경쟁하는 높은 경합은 응용의 전체 성능을 떨어뜨린다.'))
wait=code(c,'대기 큐를 사용하는 세마포 wait()',301,'wait(semaphore *S) {\n    S->value--;\n    if (S->value < 0) {\n        add this process to S->list;\n        sleep();\n    }\n}', '자원 수를 감소시키고 기다려야 하는 프로세스를 세마포 대기 리스트에 넣어 일시 중지한다.',['value를 감소시킨다.','음수이면 프로세스를 list에 넣고 sleep()으로 대기시킨다.'],['원문의 의사 코드이다. 일반 C 코드로 임의 수정하지 않았다.','세마포 연산 자체는 원자적이어야 한다.'],True)
signal=code(c,'대기 큐를 사용하는 세마포 signal()',302,'signal(semaphore *S) {\n    S->value++;\n    if (S->value <= 0) {\n        remove a process P from S->list;\n        wakeup(P);\n    }\n}', '세마포 값을 증가시키고 대기자가 있으면 하나를 꺼내 준비 상태가 되도록 깨운다.',['value를 증가시킨다.','값이 0 이하이면 list의 P를 제거하고 wakeup(P)를 수행한다.'],['깨운 프로세스가 즉시 CPU에서 실행되는지는 스케줄링에 달려 있다.'],True)
sec(c,'6.6','세마포',299,303,
 p('**세마포 S**는 정수 변수이며 초기화를 제외하고 원자적인 wait()와 signal()만으로 접근한다. 원문의 고전적 wait는 S>0이 될 때까지 바쁘게 기다린 뒤 감소시키고 signal은 증가시킨다. 검사와 감소까지 인터럽트되지 않는 하나의 동작이어야 한다.'),
 table(['유형','값·용도'],[['카운팅 세마포','유한 개 자원의 접근을 제어한다. 가용 자원 수로 초기화하고 획득 때 감소, 반환 때 증가시킨다.'],['이진 세마포','0과 1의 값만 가지며 mutex 락과 유사하게 상호 배제를 제공할 수 있다.']]),
 p('세마포는 실행 순서도 조정한다. 원문은 P₁의 S₁ 뒤에 P₂의 S₂가 실행되어야 할 때 synch를 0으로 초기화하고, S₁ 뒤에 signal(synch), S₂ 앞에 wait(synch)를 둔다. 이 순서 제약은 하나의 임계구역 보호와 구별되는 용도이다.'),
 p('바쁜 대기를 줄이는 구현에서는 세마포마다 정수 value와 프로세스 리스트 list를 둔다. wait에서 기다려야 하면 프로세스를 대기 상태로 바꾸고 CPU 스케줄러가 다른 프로세스를 선택한다. signal이 깨우면 준비 완료 상태·준비 큐로 돌아간다.'),wait,signal,
 p('이 구현에서는 음수 값의 절댓값이 대기 프로세스 수를 나타낸다. 이는 고전적 정의와 달리 감소 후 검사하기 때문이다. FIFO 큐로 대기자를 관리하면 한정된 대기를 보장하는 방법이 되지만 세마포의 정확한 사용 자체가 특정 큐잉 전략에 의존하는 것은 아니다. 단일 처리기는 연산 동안 인터럽트를 막을 수 있고 SMP는 CAS·스핀락 등의 기법이 필요하다. 바쁜 대기가 완전히 사라진 것은 아니며 짧은 세마포 연산의 임계구역에 국한된다.'))
sec(c,'6.7','모니터',303,310,
 p('세마포는 호출 순서를 잘못 쓰면 발견하기 어려운 타이밍 오류를 낳는다. signal을 먼저 하고 wait를 나중에 하면 상호 배제가 깨질 수 있고, 퇴출 시 signal 대신 wait를 하면 영구 봉쇄될 수 있다. 어느 연산을 빠뜨려도 상호 배제 위반 또는 영구 대기로 이어진다. 이런 오류를 줄이기 위해 고급 언어 구조물인 모니터를 도입한다.'),
 p('**모니터**는 내부에서 상호 배제가 보장되는 연산 집합을 포함한 추상 자료형이다. 지역 변수는 내부 함수만 접근하고 다른 프로세스가 직접 표현을 사용하지 못한다. 모니터 안에서는 항상 하나의 프로세스만 활성화된다. 프로그래머가 이 제약을 직접 코딩할 필요가 줄어든다.'),
 p('**조건 변수** x의 x.wait()는 호출자를 일시 중지하고 x.signal()은 기다리는 프로세스 하나를 재개한다. 기다리는 프로세스가 없으면 조건 변수 signal은 효과가 없다. 세마포의 signal은 항상 세마포 상태에 영향을 준다는 점과 다르다.'),
 table(['신호 후 정책','실행 관계'],[['Signal and wait','신호를 보낸 P가 기다리고 재개된 Q가 모니터를 떠나거나 다른 조건을 기다린다.'],['Signal and continue','P가 계속하며 Q는 P가 모니터를 떠나거나 다른 조건을 기다릴 때까지 대기한다.'],['절충안','P가 signal 직후 모니터를 떠나 Q가 즉시 재개되도록 한다.']]),
 p('계속 실행 정책에서는 Q가 재개할 때 기다리던 논리 조건이 이미 참이 아닐 수 있다. 원문은 Java·C# 등이 모니터 개념을 편입하고 다른 언어에서도 유사한 동기화 지원을 제공한다고 설명한다.'),
 p('세마포로 signal-and-wait 모니터를 구현할 때 mutex는 1, next는 0으로 초기화한다. next-count는 신호 후 대기하는 프로세스 수를 센다. 외부 프로시저는 mutex를 획득하고 본체를 수행한 뒤 next 대기자가 있으면 그쪽에 신호하고 아니면 mutex를 반환한다. 조건 x마다 x-sem과 x-count를 0으로 두어 조건 대기자와 신호 후 양보 관계를 연결한다.'),
 p('수행 재개 순서가 FCFS만으로 충분하지 않으면 **x.wait(c)**의 정수 c를 우선순위 번호로 저장할 수 있다. x.signal()은 가장 작은 번호의 프로세스를 재개한다. 원문의 ResourceAllocator는 자원 사용을 희망하는 최대 시간이 가장 짧은 대기자에게 하나의 자원을 준다.'),
 p('고급 도구라도 잘못된 사용 순서 자체를 보장하지 않는다. 허가 없이 자원 접근·반환, 얻은 자원 미반환, 반환 전에 재요청이 가능하다. 정확성을 위해 호출 순서를 지키는지와 모니터 밖에서 공유 자원을 직접 접근하지 않는지를 확인해야 한다. 대규모·동적 시스템에서 전수 검사는 비합리적일 수 있다는 한계도 원문에 명시된다.'))
sec(c,'6.8','라이브니스',310,312,
 p('**라이브니스(liveness)**는 프로세스가 실행 수명주기 동안 진행하도록 시스템이 충족해야 할 속성이다. 무기한 대기는 진행·한정된 대기를 위반하는 라이브니스 실패이다. 바쁜 대기도 임의의 오랜 시간 지속되면 실패가 될 수 있다.'),
 p('**교착 상태**는 집합 안의 모든 프로세스가 그 집합의 다른 프로세스만 일으킬 수 있는 사건을 기다리는 상황이다. 원문은 1로 초기화한 S, Q를 두 프로세스가 서로 반대 순서로 wait하여 각자 상대의 signal을 영원히 기다리는 예를 든다.'),
 p('**우선순위 역전**은 높은 우선순위 H가 낮은 우선순위 L이 점유한 자원을 기다리는 동안 중간 우선순위 M이 L을 선점하여 H의 대기까지 길게 하는 문제이다. 원문은 세 단계 이상의 우선순위를 가진 시스템에서 설명한다. **우선순위 상속**은 해당 자원을 사용하는 L이 사용 완료까지 H의 우선순위를 물려받게 하고 이후 원래 값으로 돌려, M의 선점을 막는다. Mars Pathfinder의 반복 리셋 사례는 우선순위 상속을 활성화하여 해결한 원문 사례로 제시된다.'))
sec(c,'6.9','평가',312,314,
 p('하드웨어 명령은 낮은 수준의 기반이며 CAS로 락 없는 알고리즘도 만들 수 있다. 이런 알고리즘은 오버헤드가 낮고 확장성 장점이 있지만 개발·테스트가 어렵다. CAS는 먼저 갱신을 시도하고 충돌하면 재시도하는 낙관적 접근, 상호 배제 락은 다른 갱신자가 있다고 가정하고 먼저 획득하는 비관적 접근으로 대비된다.'),
 table(['경합','원문의 일반적 성능 지침'],[['없음','양쪽 모두 빠르지만 CAS 보호가 기존 동기화보다 다소 빠를 수 있다.'],['적당함','CAS는 대개 성공하며 실패해도 재시도가 적어 기존 동기화보다 빠를 수 있다.'],['심함','반복 충돌이 커지므로 기존 동기화가 기본적으로 CAS보다 빠르다.']]),
 p('한 개 공유 변수 갱신에는 원자적 정수가 가볍다. 임계구역 접근 보호에는 mutex가 이진 세마포보다 간단하고 오버헤드가 적어 선호되지만, 유한 개 자원 제어에는 카운팅 세마포가 적합하다. 여러 reader를 동시에 허용하는 reader-writer 락은 병행성을 높일 수 있다. 모니터·조건 변수는 사용이 간단하지만 구현에 따라 오버헤드와 높은 경합에서의 확장성 한계가 있다.'))
sec(c,'6.10','요약',315,317,p('경쟁 조건은 공유 접근의 순서 의존성에서 발생한다. 임계구역 해결은 상호 배제·진행·한정된 대기를 함께 검토해야 한다. 하드웨어의 가시성과 원자성이 소프트웨어 도구의 토대이며, 세마포·모니터도 올바른 순서와 라이브니스 점검이 필요하다. 원문 연습 문제는 인터럽트 금지와 클록, 바쁜 대기, 단일·다중 처리기에서의 스핀락, 세마포 연산의 원자성 및 공유 은행 계좌의 경쟁 조건을 점검한다. 새 답안은 만들지 않았다.'))
finish(c,['경쟁 조건의 핵심은 공유 데이터와 접근 순서에 따른 결과 변화이다.','임계구역 해법은 상호 배제·진행·한정된 대기 세 조건을 만족해야 한다.','명령 재정렬·메모리 가시성과 원자적 갱신은 구별한다.','조건 변수 signal은 대기자가 없으면 효과가 없지만 세마포 signal은 상태를 바꾼다.','상호 배제만 확인하지 말고 교착 상태·우선순위 역전·경합 성능도 점검한다.'],['공유 데이터 → 경쟁 조건 → 임계구역 프로토콜의 관계를 연결한다.','하드웨어 지원 → 원자적 변수·락 → 세마포·모니터로 추상화 수준이 높아진다.','바쁜 대기와 봉쇄 대기의 비용은 문맥 교환과 경합 정도에 따라 다르다.'],[('임계구역의 세 요구 조건과 차이를 설명할 수 있는가?',286,287),('Peterson 해결안의 두 프로세스 전제와 현대 구조에서의 한계를 설명할 수 있는가?',288,292),('세마포 대기 큐 구현에서 음수 값과 wakeup의 의미를 설명할 수 있는가?',301,303),('모니터 조건 변수의 signal과 세마포 signal의 차이를 설명할 수 있는가?',305,307),('우선순위 역전과 우선순위 상속의 관계를 설명할 수 있는가?',312,313)], [('경쟁 상황','6.1'),('임계구역','6.2'),('Peterson의 해결안','6.3'),('메모리 장벽','6.4.1'),('CAS','6.4.2'),('원자적 변수','6.4.3'),('스핀락','6.5'),('세마포','6.6'),('모니터','6.7'),('조건 변수','6.7'),('라이브니스','6.8'),('우선순위 역전','6.8')])

c=chapter(7)
c['overview']=['유한 버퍼·readers-writers·식사하는 철학자 문제에 동기화 도구를 적용하고, Windows·Linux 커널 및 POSIX·Java의 구현과 API를 비교한다.','트랜잭션 메모리·OpenMP·함수형 언어도 원문이 제시하는 동기화 대안으로 정리한다.']
c['flow']=['고전적 문제의 공유 상태와 동기화 조건 → 커널의 동기화 도구','POSIX의 락·세마포·조건 변수 → Java 모니터와 명시적 락','전통적인 락 사용의 한계 → 트랜잭션·컴파일러 지시·언어 방식']
sec(c,'7.1','고전적인 동기화 문제들',319,327,p('원문은 새 동기화 방법의 능력을 확인하는 대표 문제로 세 가지 문제를 제시한다. 세마포로 일반 구조를 설명하되 실제 구현에서는 이진 세마포 대신 mutex 락을 사용할 수 있다고 구별한다.'))
prod=code(c,'유한 버퍼 생산자 구조',320,'while (true) {\n    . . .\n    /* produce an item in next_produced */\n    . . .\n    wait(empty);\n    wait(mutex);\n    . . .\n    /* add next_produced to the buffer */\n    . . .\n    signal(mutex);\n    signal(full);\n}', '빈 버퍼를 확보하고 버퍼 풀을 배타적으로 수정한 뒤 채워진 버퍼 수를 알린다.',['empty를 기다린 후 mutex를 획득한다.','항목을 넣고 mutex를 반환한다.','full에 신호한다.'],['원문 그림 안의 생략 표기를 그대로 유지한 구조용 의사 코드이다.'],True)
cons=code(c,'유한 버퍼 소비자 구조',321,'while (true) {\n    wait(full);\n    wait(mutex);\n    . . .\n    /* remove an item from buffer to next_consumed */\n    . . .\n    signal(mutex);\n    signal(empty);\n    . . .\n    /* consume the item in next_consumed */\n    . . .\n}', '채워진 버퍼를 기다려 항목을 꺼낸 뒤 빈 버퍼가 생겼음을 알린다.',['full을 기다린 후 mutex를 획득한다.','항목을 제거하고 mutex를 반환한다.','empty에 신호하고 가져온 항목을 소비한다.'],['생산자는 소비자를 위해 채워진 버퍼를, 소비자는 생산자를 위해 빈 버퍼를 만든다는 대칭성이 핵심이다.','원문 자체의 생략 표기를 보존하였다.'],True)
sec(c,'7.1.1','유한 버퍼 문제',320,321,
 p('n개의 버퍼는 각각 한 항목을 저장한다. **mutex=1**은 버퍼 풀의 배타적 접근, **empty=n**은 빈 버퍼 수, **full=0**은 채워진 버퍼 수를 나타낸다. 자원 수를 기다리는 세마포와 실제 버퍼 조작을 보호하는 세마포의 역할을 분리하여 읽는다.'),prod,cons)
sec(c,'7.1.2','Readers-Writers 문제',321,323,
 p('여러 reader가 동시에 읽는 것은 허용하지만 writer는 읽는 스레드나 다른 writer와 동시에 공유 데이터베이스에 접근하면 안 된다. 쓰는 동안 배타적 접근을 보장하는 문제가 **readers-writers 문제**이다.'),
 table(['변형','우선 규칙','기아 가능성'],[['첫 번째 문제','writer가 아직 접근 허가를 얻지 못했다면, writer가 기다린다는 이유만으로 새 reader를 기다리게 하지 않는다.','writer'],['두 번째 문제','writer가 준비되어 기다리면 새 reader의 읽기 시작을 막아 가능한 빨리 쓰게 한다.','reader']]),
 p('원문은 첫 번째 문제의 세마포 해법을 제시한다. read_count는 읽는 프로세스 수, mutex는 그 수의 갱신 보호, rw_mutex는 writer의 배타적 접근과 reader 집단의 접근을 조정한다. 첫 reader가 rw_mutex를 기다리고 마지막 reader가 반환하며, 중간 reader들은 rw_mutex를 다시 기다리지 않는다. writer가 반환할 때 여러 reader 또는 writer 한 개 중 어느 쪽이 진행할지는 스케줄러에 달린다.'),
 p('**Reader-writer 락**은 획득할 때 읽기·쓰기 모드를 지정한다. 읽기 모드는 여러 프로세스가 동시에 얻을 수 있지만 쓰기는 하나만 얻는다. 읽기 전용과 쓰기를 식별하기 쉽고 reader가 writer보다 많은 응용에 유용하다. 설정 오버헤드는 mutex·세마포보다 크지만 여러 reader의 병행성으로 이를 상쇄할 수 있다.'))
din=fig(c,'식사하는 철학자 문제의 모니터 해법',326,(.18,.335,.91,.936),'그림 7.7. 모니터 의사 코드 전체. 원문 자체의 표기를 보존하였다.','pickup은 HUNGRY로 바꾸고 양옆의 식사 상태를 검사하며 불가능하면 자기 조건 변수에서 기다린다. putdown은 THINKING으로 바꾼 뒤 양옆 대기자를 검사한다. 원문에 실행 결과 미제시.')
sec(c,'7.1.3','식사하는 철학자들 문제',323,327,
 p('원형 테이블의 철학자 5명은 생각과 식사를 반복하고 각각 왼쪽·오른쪽 젓가락 두 개가 있어야 식사할 수 있다. 이는 **교착 상태와 기아 없이 여러 스레드에 여러 자원을 할당하는 문제**를 표현한다. 각 젓가락을 초기값 1의 세마포로 두고 모두 왼쪽부터 기다리게 하면 이웃의 동시 식사는 막지만 모두 왼쪽만 얻은 채 오른쪽을 기다리는 교착 상태가 가능하다.'),
 bullets('동시에 테이블에 앉는 철학자를 최대 4명으로 제한할 수 있다.','임계구역 안에서 두 젓가락을 모두 집을 수 있을 때에만 집도록 할 수 있다.','홀수는 왼쪽부터, 짝수는 오른쪽부터 집게 하는 비대칭 순서를 사용할 수 있다.'),
 p('모니터 해법은 각 철학자를 THINKING·HUNGRY·EATING 상태로 구별하고 양옆 이웃이 EATING이 아닐 때만 먹게 한다. 각자 self 조건 변수로 기다리며 pickup → 식사 → putdown 순서를 지킨다. 이 해법은 이웃의 동시 식사와 교착 상태를 막지만 **기아 가능성까지 없애지는 않는다**.'),din)
sec(c,'7.2','커널 안에서의 동기화',327,330,
 p('Windows는 단일 처리기에서 전역 정보를 접근할 때 관련 인터럽트 핸들러 실행을 잠시 막고, 다중 처리기에서는 짧은 코드에 스핀락을 사용한다. 스핀락 소유 중에는 선점되지 않도록 한다. 커널 밖 스레드 동기화에는 mutex·세마포·event·타이머 등의 **dispatcher 객체**를 제공한다.'),
 table(['Dispatcher 상태','객체와 스레드의 관계'],[['Signaled','객체가 사용 가능하고 획득 시 봉쇄되지 않는다.'],['Nonsignaled','객체가 사용 불가능하다. 획득하려는 스레드는 대기 상태·객체 대기 큐로 간다.'],['다시 signaled가 됨','커널은 객체 종류에 따라 하나 또는 여러 대기 스레드를 준비 상태로 옮긴다. Mutex는 하나, event는 기다리는 모든 스레드가 대상일 수 있다.']]),
 p('Windows의 critical-section 객체는 사용자 모드 mutex이며 커널 개입 없이 획득·반환할 수 있다. 다중 처리기에서는 먼저 회전하고 회전이 길면 커널 mutex를 할당하여 CPU를 양보한다. 경쟁이 있을 때만 커널 mutex 비용을 부담하는 방식이다.'),
 p('원문이 설명하는 Linux 커널은 선점 가능하며 원자적 정수 atomic_t, mutex, 스핀락·세마포 및 reader-writer 형태를 제공한다. 단순 정수 갱신에는 원자적 연산이 효율적이지만 여러 변수가 관련된 경쟁에는 더 정교한 도구가 필요하다. mutex_lock()이 락을 얻지 못하면 수면하고 소유자가 반환할 때 깨어난다.'),
 table(['환경','짧은 구역 보호'],[['단일 처리기','커널 선점을 불가능하게 하고 끝나면 다시 가능하게 한다.'],['다중 처리기','스핀락을 획득하고 끝나면 방출한다.']]),
 p('원문의 Linux 스핀락·mutex는 재귀적이지 않다. 같은 스레드가 해제 없이 다시 획득하려 하면 봉쇄된다. 각 스레드의 preempt_count로 소유 락 수를 추적하며 0보다 크면 커널 선점이 안전하지 않다. 락이 오래 유지되면 스핀락보다 세마포·mutex를 사용하는 것이 적합하다고 설명한다.'))
cond=code(c,'Pthread 조건 변수로 a == b를 기다림',333,'pthread_mutex_lock(&mutex);\nwhile (a != b)\n    pthread_cond_wait(&cond_var, &mutex);\n\npthread_mutex_unlock(&mutex);','조건 데이터 확인을 mutex로 보호하면서 조건이 참이 아니면 조건 변수에서 기다린다.',['mutex를 먼저 획득하고 a와 b를 비교한다.','wait가 mutex를 해제하여 다른 스레드가 데이터를 갱신할 수 있게 한다.','신호 후 락을 다시 얻어 조건을 루프에서 재확인한다.'],['원문은 프로그램 오류 방지를 위해 신호 후 조건을 다시 확인하는 루프가 중요하다고 명시한다.'],True)
sec(c,'7.3','POSIX 동기화',330,334,
 p('POSIX API는 특정 커널의 내부 기능과 달리 사용자 수준 프로그래머가 쓰는 인터페이스이다. pthread_mutex_t를 pthread_mutex_init()으로 초기화하고, 두 번째 인자로 NULL을 주면 기본 속성을 쓴다. pthread_mutex_lock()과 pthread_mutex_unlock()으로 임계구역 전후를 보호하며 사용 중인 락을 요청한 스레드는 반환까지 봉쇄된다. 원문은 성공 시 0, 오류 시 0이 아닌 코드가 반환된다고 설명한다.'),
 p('세마포는 Pthreads 자체의 일부가 아닌 POSIX SEM 확장에 속하지만 많은 구현에서 함께 제공된다. **기명 세마포**는 sem_open()으로 생성·열고 관련 없는 프로세스도 이름을 이용해 같은 세마포를 공유한다. 원문의 "SEM", O_CREAT, 0666, 1 예는 없을 때 생성, 다른 프로세스의 읽기·쓰기 권한, 초기값 1을 뜻한다.'),
 table(['구분','생성·공유'],[['기명','이름으로 공통 세마포에 접근한다. sem_open()은 기존 세마포의 디스크립터도 반환한다.'],['무명','sem_init()에 세마포 포인터·공유 플래그·초기값을 전달한다. 플래그 0은 같은 프로세스의 스레드 사이 공유, 0이 아니면 공유 메모리 영역에 두어 프로세스 사이 공유할 수 있다.']]),
 p('두 유형 모두 sem_wait()로 획득하고 sem_post()로 반환한다. Pthread 조건 변수는 pthread_cond_t와 pthread_cond_init()으로 선언·초기화하고 mutex와 연결한다. C에는 언어 수준 모니터가 없으므로 별도 mutex가 조건 데이터의 무결성을 지킨다.'),cond,
 p('공유 데이터를 갱신하는 쪽은 mutex를 얻고 값을 바꾼 다음 pthread_cond_signal()로 대기자 하나에 신호하고 mutex를 해제한다. **signal 호출 자체는 mutex를 해제하지 않는다.** 뒤의 pthread_mutex_unlock()으로 락이 풀리면 신호받은 스레드가 락 소유권을 얻고 wait 호출에서 실행을 재개한다.'))
java=code(c,'Java ReentrantLock의 획득·반환',339,'Lock key = new ReentrantLock();\n\nkey.lock();\ntry {\n    /* critical section */\n}\nfinally {\n    key.unlock();\n}','명시적 락으로 공유 자원에 상호 배타적으로 접근하며 finally에서 반환한다.',['lock()으로 획득한 뒤 try 본체에서 임계구역을 수행한다.','정상 완료 또는 try 안 예외 발생 때 finally에서 해제한다.'],['원문은 lock()을 try 밖에 둔다. 획득 실패 예외가 생겼는데 finally에서 해제하면 다른 예외로 원래 실패가 가려질 수 있기 때문이다.'],True)
sec(c,'7.4','Java에서의 동기화',334,342,
 p('Java 객체마다 락이 연결된다. **synchronized 메소드**는 해당 객체 락을 얻은 스레드만 진입하고 종료하면 반환한다. 다른 스레드는 객체의 **진입 집합(entry set)**에서 락이 풀리기를 기다린다. JVM 명세는 선택 순서를 강제하지 않는다고 원문은 설명한다. 공유 데이터를 조작하는 부분만 synchronized 블록으로 감싸면 전체 메소드보다 **락 범위(lock scope)**를 줄일 수 있다.'),
 p('객체에는 별도로 **대기 집합(wait set)**도 있다. 락을 가진 스레드가 조건을 만족하지 못하면 wait()를 호출하여 락을 해제하고 봉쇄 상태가 되어 대기 집합으로 간다. notify()는 대기자 하나를 선택하여 진입 집합으로 옮기고 실행 가능 상태로 바꾼다. 이 스레드는 락을 다시 얻은 후에야 wait에서 돌아와 조건을 확인한다. 대기자가 없으면 notify는 무시된다.'),
 steps('원문의 가득 찬 유한 버퍼 처리','생산자가 insert()에서 버퍼가 가득 찼음을 확인하고 wait()하여 락을 놓는다.','소비자가 remove()에 진입해 항목을 제거하고 notify()한다. 이 순간에도 소비자가 락을 소유한다.','생산자는 대기 집합에서 진입 집합으로 이동한다.','소비자가 메소드를 종료하여 락을 반환한다. 생산자가 다시 획득하여 루프에서 빈 공간을 재확인하고 삽입한다.'),
 fig(c,'Java 객체의 진입 집합과 대기 집합',337,(.20,.793,.91,.94),'그림 7.12. 원문 관계도.','객체 락의 소유자는 하나이며 진입 대기와 조건 대기를 구별한다. notify가 즉시 락을 넘기는 것으로 해석하지 않는다.'),
 p('**ReentrantLock**은 한 스레드가 소유하며 공정성 설정 등 추가 기능을 제공한다. 호출자가 이미 소유한 락도 다시 획득할 수 있어 재진입이라고 부른다. 사용할 수 없는 락은 unlock()으로 배정 가능해질 때까지 기다린다. 읽기만 하는 스레드의 병행성을 위해 ReentrantReadWriteLock도 제공된다.'),java,
 p('Java의 카운팅 세마포는 Semaphore(int value)로 초기화하며 원문은 음수 초기값도 허용한다고 설명한다. acquire()는 인터럽트되면 InterruptedException을 던질 수 있다. 원문 예는 release()를 finally에 둔다. 조건 변수는 ReentrantLock의 newCondition()에서 얻으며 await()·signal()을 사용한다.'),
 p('언어 수준 Java 모니터의 wait·notify는 객체의 무명 조건 변수 하나에 연결된다. 명시적 **Condition**은 기다리는 조건을 나누어 특정 조건의 대기자에게 알릴 수 있다. 원문의 5스레드 순번 예는 각 조건 변수 배열에서 자기 차례를 기다리고 작업 후 다음 turn에 신호한다. await는 연결된 재진입 락을 해제하지만 signal은 조건에만 알리며 실제 해제는 unlock()이 수행한다.'))
sec(c,'7.5','대체 방안들',342,345,
 p('**트랜잭션 메모리**의 메모리 트랜잭션은 메모리 읽기·쓰기 연산의 원자적인 순서이다. 모든 연산이 완수되면 commit하고 그렇지 않으면 수행한 변경을 취소하여 시작 전으로 rollback한다. 원문이 가정한 atomic { S } 구조에서는 개발자 대신 트랜잭션 시스템이 원자성을 보장한다. 락을 쓰지 않는 이 방법에서는 락에 의한 교착 상태가 없고 병행 가능한 읽기를 시스템이 식별할 수 있다고 설명한다.'),
 table(['구현','원문의 방식과 한계'],[['STM','특수 하드웨어 없이 컴파일러가 검사 코드를 넣어 동시 실행·저수준 락이 필요한 지점을 관리한다.'],['HTM','캐시 계층과 일관성 프로토콜로 충돌을 관리한다. 코드 계측 오버헤드가 작지만 하드웨어 구조의 변경이 필요하다.']]),
 p('**OpenMP**는 컴파일러 지시와 API로 공유 메모리 병렬성을 제공한다. #pragma omp critical 뒤 코드 구역은 한순간 하나의 스레드만 실행한다. 여러 임계구역에 이름을 주면 같은 이름을 가진 구역에서 동시에 두 스레드가 활동할 수 없다. 표준 mutex보다 사용이 쉽지만 개발자가 경쟁 가능성을 찾아 보호해야 하며 여러 임계구역이 관여하면 교착 상태가 여전히 가능하다.'),
 p('**함수형 프로그래밍 언어**는 명령형 언어의 변경 가능한 상태와 다른 방식을 따른다. 원문은 한 번 값이 배정된 변수는 바뀌지 않는다는 점 때문에 이 장의 공유 상태 경쟁·교착 문제를 피하는 방향으로 설명하고 Erlang·Scala를 언급한다. 이 비교는 원문이 기술하는 범위에 한정하며 다른 언어 특성을 덧붙이지 않는다.'))
sec(c,'7.6','요약',345,347,p('세 고전 문제는 자원 수 제어·읽기와 쓰기의 병행성·여러 자원 동시 할당을 각각 드러낸다. 커널 내부 동기화와 사용자 수준 POSIX·Java API를 구별하고, 락 소유권과 조건 대기의 이동을 함께 본다. 원문 연습 문제는 운영체제가 여러 락을 제공하는 이유, 철학자 교착, dispatcher 상태, 원자적 정수 연산 등을 확인한다. 외부 API 설명이나 새 계산 결과를 추가하지 않았다.'))
finish(c,['유한 버퍼에서 empty·full은 자원 수, mutex는 버퍼 조작의 상호 배제를 담당한다.','Reader 우선과 writer 우선은 서로 다른 쪽의 기아 가능성을 가진다.','철학자 모니터의 교착 상태 방지와 기아 방지는 같은 보장이 아니다.','조건 대기와 신호는 락의 획득·해제와 구별하며 재개 후 조건을 확인한다.','Java의 진입 집합·대기 집합과 POSIX 조건 변수의 mutex 관계를 구분한다.'],['고전 문제의 요구 조건 → 세마포·모니터의 상태와 연산 순서를 연결한다.','커널의 짧은 보호에는 스핀·선점 제어, 오래 기다리는 상황에는 봉쇄 도구라는 원문 맥락을 복습한다.','트랜잭션·OpenMP·함수형 방식은 각각 원자성 책임·지시 기반 보호·상태 모델을 바꾸는 접근으로 읽는다.'],[('유한 버퍼 생산자·소비자의 wait와 signal 순서를 설명할 수 있는가?',320,321),('Reader 우선과 writer 우선의 기아 가능성을 구분할 수 있는가?',321,323),('철학자 문제에서 상호 배제·교착·기아의 차이를 설명할 수 있는가?',324,327),('POSIX 조건 변수의 wait와 signal이 mutex에 미치는 영향을 설명할 수 있는가?',333,334),('Java notify 이후 락 재획득까지의 단계를 설명할 수 있는가?',335,339),('STM과 HTM 및 OpenMP의 조건과 한계를 설명할 수 있는가?',342,345)],[('유한 버퍼','7.1.1'),('Readers-Writers','7.1.2'),('식사하는 철학자','7.1.3'),('Dispatcher 객체','7.2'),('POSIX 동기화','7.3'),('기명 세마포','7.3'),('Java 모니터','7.4'),('ReentrantLock','7.4'),('트랜잭션 메모리','7.5'),('OpenMP 임계구역','7.5')])

c=chapter(8)
c['overview']=['한정된 자원을 점유하고 서로 기다리는 교착 상태를 시스템 모델과 자원 할당 그래프로 표현한다.','예방·회피·탐지·회복의 차이, 안전 상태와 은행원 알고리즘의 조건을 원문의 그래프·행렬 예와 함께 정리한다.']
c['flow']=['요청·사용·방출 모델 → 다중 스레드 교착·라이브락','네 필요조건과 자원 할당 그래프 → 예방과 안전 상태 기반 회피','은행원 알고리즘 → 현재 상태 탐지 → 종료·선점으로 회복']
sec(c,'8.1','시스템 모델',349,351,
 p('자원은 유한하며 여러 유형으로 나뉜다. 같은 유형의 인스턴스들은 서로 동등하여 그중 어느 것을 할당해도 요청을 충족해야 한다. CPU·파일·입출력 장치뿐 아니라 mutex·세마포도 자원이다. 각 락은 보호하는 자료구조가 다르므로 일반적으로 고유한 자원 클래스로 취급한다.'),
 steps('정상 자원 사용 순서','요청: 즉시 허용되지 않으면 자원을 얻을 때까지 기다린다.','사용: 할당받은 자원을 이용하여 작업한다.','방출: 사용을 마치면 반환한다.'),
 p('운영체제는 자원의 가용·할당 상태와 소유 스레드를 기록하고 사용할 수 없는 자원 요청자를 대기 큐에 둘 수 있다. **교착 상태**는 집합 안의 모든 스레드가 그 집합의 다른 스레드만 일으킬 수 있는 사건을 기다리는 상황이다. 주로 자원 획득·방출을 다루지만 IPC 등 다른 사건도 원인이 될 수 있다.'))
sec(c,'8.2','다중 스레드 응용에서의 교착 상태',351,354,
 p('원문의 두 Pthread 스레드는 first_mutex와 second_mutex를 서로 반대 순서로 획득한다. 한쪽이 first_mutex, 다른 쪽이 second_mutex를 소유한 후 상대 락을 요청하면 둘 다 기다린다. 그러나 한 스레드가 두 락을 얻고 모두 반환한 다음 다른 스레드가 시작하면 교착은 없다. **가능한 코드 구조와 실제 특정 실행에서의 발생을 구분해야 한다.** 특정 스케줄링에서만 드러나므로 검사도 어렵다.'),
 p('**라이브락(livelock)**은 스레드가 봉쇄되지는 않지만 실패하는 행동을 계속 재시도하여 진행하지 못하는 장애이다. 원문은 trylock으로 두 번째 락을 얻지 못하면 자기 락을 반환하고 다시 시도하는 두 스레드를 예로 든다. 서로 동시에 반복하면 계속 실패할 수 있다. 원문은 일반적으로 재시도 시간을 무작위화하여 피하는 접근을 설명하고 Ethernet 충돌 후 재전송 대기와 연결한다.'),
 table(['장애','진행하지 못하는 이유'],[['교착 상태','집합 내 다른 스레드만 발생시킬 수 있는 사건을 기다리며 봉쇄된다.'],['라이브락','실패한 행동을 계속 재시도하여 봉쇄 없이도 앞으로 나아가지 못한다.']]))
sec(c,'8.3','교착 상태 특성',353,358,
 table(['필요조건','원문의 의미'],[['상호 배제','최소 한 자원이 비공유 모드로 점유되어 한 번에 한 스레드만 사용한다.'],['점유하며 대기','최소 한 자원을 소유하면서 다른 스레드 소유 자원을 추가로 기다린다.'],['비선점','자원은 강제로 회수할 수 없고 소유자가 작업을 마친 뒤 자발적으로 반환한다.'],['순환 대기','대기 스레드들의 각자가 다음 스레드가 점유한 자원을 기다리는 고리가 있다.']]),
 p('교착 상태가 가능하려면 네 조건이 **동시에** 성립해야 한다. 순환 대기는 점유하며 대기를 암시하므로 완전히 독립적인 조건은 아니지만 예방 방법을 설명하기 위해 나누어 본다.'),
 p('**자원 할당 그래프**는 스레드를 원, 자원 유형을 사각형, 각 인스턴스를 사각형 내부 점으로 표시한다. 스레드 → 자원은 요청 간선, 인스턴스 → 스레드는 할당 간선이다. 요청이 충족되면 요청 간선을 할당 간선으로 바꾸고 반환하면 할당 간선을 지운다.'),
 table(['그래프 조건','판단'],[['사이클 없음','교착 상태가 없다.'],['사이클의 자원 유형이 각각 단일 인스턴스','사이클은 교착 상태의 필요충분조건이다.'],['여러 인스턴스를 가진 자원 유형 포함','사이클은 필요조건이지만 충분조건은 아니다. 다른 스레드의 반환으로 고리를 풀 수 있다.']]),
 fig(c,'교착 상태인 자원 할당 그래프',357,(.39,.68,.70,.943),'그림 8.5. 원문 그래프.','T₁·T₂·T₃가 서로 점유한 자원 반환을 기다린다. R₂의 인스턴스가 둘이어도 이 그림의 두 인스턴스는 기다리는 스레드에 점유되어 있다.'),
 fig(c,'사이클이 있지만 교착 상태가 아닌 그래프',358,(.32,.096,.77,.351),'그림 8.6. 원문 그래프.','T₄가 R₂ 인스턴스를 반환하면 T₃에 할당할 수 있어 사이클이 사라진다. 따라서 여러 인스턴스에서는 사이클만으로 교착 상태라고 단정할 수 없다.'))
sec(c,'8.4','교착 상태 처리 방법',358,360,
 table(['접근','기준과 비용'],[['무시','교착이 발생하지 않는 것으로 취급한다. 원문은 드문 발생에 비해 지속적인 처리 비용이 클 수 있고 수동 복구를 사용할 수 있다고 설명한다.'],['예방·회피','절대 교착 상태가 되지 않게 제약하거나 현재 할당을 허가할지 판단한다.'],['탐지 후 회복','교착을 허용하되 상태 조사 알고리즘과 복구 알고리즘을 둔다.']]),
 p('**예방**은 네 필요조건 중 적어도 하나를 성립하지 않게 하도록 자원 요청 방법을 제한한다. **회피**는 스레드의 미래 최대 요구 등 추가 정보를 알고 현재 가용·할당 상태와 함께 요청 허가를 결정한다. 탐지·회복이 없으면 인식하지 못한 교착이 점차 자원을 묶어 시스템 성능을 낮출 수 있다. 자원 클래스별로 다른 기본 방법을 조합할 수도 있다.'))
sec(c,'8.5','교착 상태 예방',360,364,
 table(['깨뜨릴 조건','방법','한계'],[['상호 배제','가능한 자원을 공유 가능하게 한다.','읽기 전용 파일과 달리 mutex 같은 자원은 본래 공유할 수 없어 일반적인 해결이 안 된다.'],['점유하며 대기','실행 전에 모두 요청하거나, 아무 자원도 없을 때만 새 요청을 허용한다.','오래 사용하지 않는 자원을 점유하여 이용률이 낮고 필요한 자원을 한꺼번에 얻지 못하는 기아가 가능하다.'],['비선점','새 요청을 즉시 못 들어주면 이미 가진 자원을 회수하고 나중에 함께 재획득한다. 또는 대기 중인 다른 스레드에서 선점한다.','상태 저장·복원이 쉬운 CPU 레지스터·트랜잭션 등에 적용되지만 mutex·세마포에는 일반적으로 적용되지 않는다.'],['순환 대기','모든 자원 유형에 전체 순서를 부여하고 오름차순 요청을 강제한다.','순서 설정만으로는 부족하며 프로그램이 지켜야 한다. 동적 락 획득에도 주의한다.']]),
 p('순환 대기 예방에서 함수 F는 각 자원 유형에 고유 자연수 번호를 준다. 이미 Rᵢ를 가진 스레드는 더 큰 번호의 자원만 요청한다. 같은 유형의 인스턴스가 여러 개 필요하면 한 번의 요청으로 모두 받아야 한다. 대안은 새 자원 이상 순서의 기존 자원을 모두 먼저 반환하게 하는 것이다. 순환 고리가 있다면 순서가 계속 증가하여 결국 자기보다 작아져야 하는 모순이 생긴다는 것이 원문의 증명이다.'),
 p('원문의 계좌 이체 예는 from·to 인자에 따라 동적으로 락을 얻으면 두 스레드가 반대 계좌 순서로 호출하여 교착할 수 있음을 보인다. Linux lockdep은 실행 중 락 획득·반환 패턴과 인터럽트 활성 상태를 검사하여 잠재적 교착을 보고한다. 원문은 개발·수정 검사 도구이며 속도 저하 때문에 실제 운영용으로 쓰지 않는다고 설명한다. 외부 도구 사용법은 덧붙이지 않았다.'))
sec(c,'8.6','교착 상태 회피',363,371,
 p('예방의 요청 제한은 이용률·처리율을 낮출 수 있다. 회피는 각 스레드의 **최대 요구 수** 같은 추가 정보를 받아 요청 후의 할당 상태를 판단한다. 상태는 가용 자원 수·현재 할당 수·최대 요구 수로 표현한다. 현재 여유 자원이 충분하다는 사실만으로 요청을 허용하지 않는다.'))
sec(c,'8.6.1','안전 상태',365,366,
 p('**안전 상태**는 모든 스레드가 최대 요구량을 요청해도 어떤 순서로 하나씩 끝낼 수 있는 **안전 순서**가 있는 상태이다. 순서의 각 스레드에 필요한 추가 자원은 현재 가용량과 앞서 끝난 스레드가 반납할 자원으로 충족해야 한다. 즉시 만족할 수 없다면 앞선 스레드의 종료까지 기다리게 한다.'),
 p('안전 상태는 교착 상태가 아니다. 교착 상태는 불안전하지만 **불안전 상태가 반드시 교착 상태인 것은 아니다**. 이후 실제 요청에 따라 교착할 수 있다는 뜻이다. 원문의 12개 자원 예는 최대 요구 10·4·9, 현재 점유 5·2·2, 가용 3에서 T₁ → T₀ → T₂로 모두 끝낼 수 있다. 여기서 T₂에 하나 더 주면 남은 요청을 모두 처리할 안전 순서가 없어 불안전해진다. 회피는 항상 안전 상태 안에 머무르게 하므로 가용 자원이 있어도 대기시킬 수 있다.'))
sec(c,'8.6.2','자원 할당 그래프 알고리즘',366,367,
 p('각 자원 유형에 인스턴스가 하나씩인 경우 미래에 요청할 수 있음을 **예약 간선(claim edge)**이라는 점선으로 표시한다. 실행 전 모든 예약을 표시하며 실제 요청 시 요청 간선으로, 반환 시 할당 간선을 예약 간선으로 되돌린다. 모든 관련 간선이 예약인 경우에만 새 예약을 추가하도록 조건을 완화할 수 있다.'),
 p('요청 간선을 할당 간선으로 바꾸어도 사이클이 생기지 않는 경우에만 허용한다. 생기면 불안전해지므로 자원이 현재 가용해도 기다리게 한다. 원문은 사이클 검사에 n² 차수의 연산이 필요하다고 설명한다. 여러 인스턴스의 경우는 다음 은행원 알고리즘으로 다룬다.'))
sec(c,'8.6.3','은행원 알고리즘',368,371,
 p('스레드는 시작할 때 자원 유형별 최대 개수를 미리 신고하며 총 보유량을 넘을 수 없다. 시스템은 요청을 들어준 뒤에도 안전한지 검사한다. 아래에서 n은 스레드 수, m은 자원 유형 수이며 벡터 비교는 모든 성분별 비교이다.'),
 table(['자료구조','크기와 의미'],[['Available','m 벡터. 유형별 현재 가용 개수.'],['Max','n×m 행렬. 스레드별 유형별 최대 요구.'],['Allocation','n×m 행렬. 현재 할당된 개수.'],['Need','n×m 행렬. 앞으로 추가 요청할 수 있는 개수. Need[i][j] = Max[i][j] − Allocation[i][j].']]),
 fig(c,'은행원 안전성 알고리즘',369,(.17,.146,.91,.49),'8.6.3.1 원문 알고리즘.','Work=Available, Finish=false에서 시작하여 Needᵢ≤Work인 미완료 스레드를 찾아 끝낼 수 있다고 보고 Allocationᵢ를 Work에 돌려준다. 모두 Finish=true이면 안전하다. 원문의 부등호·기호를 보존하였다.'),
 steps('자원 요청 검사','Requestᵢ ≤ Needᵢ인지 검사한다. 아니면 오류로 처리한다.','Requestᵢ ≤ Available인지 검사한다. 아니면 당장 자원이 없어 대기한다.','가상으로 할당해 Available을 줄이고 Allocationᵢ를 늘리며 Needᵢ를 줄인다.','새 상태가 안전하면 확정하고, 불안전하면 이전 상태로 복원하고 기다리게 한다.'),
 fig(c,'은행원 알고리즘의 원문 행렬 예',370,(.33,.222,.735,.353),'8.6.3.3의 최초 Allocation·Max·Available 표.','총 자원은 A=10, B=5, C=7이고 Available=(3,3,2)이다. 표의 값은 원문 그대로 보존하였다.'),
 p('원문 최초 Need는 T₀=(7,4,3), T₁=(1,2,2), T₂=(6,0,0), T₃=(0,1,1), T₄=(4,3,1)이다. 안전 순서 T₁ → T₃ → T₄ → T₂ → T₀가 있다. T₁의 (1,0,2) 요청을 가상 할당하면 Available=(2,3,0)이 되고 T₁ → T₃ → T₄ → T₀ → T₂가 안전하므로 즉시 허용한다. 이어 T₄의 (3,3,0)은 자원 부족, T₀의 (0,2,0)은 자원이 있어도 불안전하므로 허용하지 않는 것이 원문의 결과이다. 새 순서나 계산을 추가하지 않았다.'))
sec(c,'8.7','교착 상태 탐지',371,375,
 p('예방·회피를 사용하지 않는 시스템은 교착 발생 여부를 검사하고 발생하면 회복할 방법이 필요하다. 실행 상태 정보 유지·탐지 알고리즘 실행·복구 손실이 모두 오버헤드이다.'),
 p('각 자원 유형이 하나씩이면 자원 할당 그래프에서 자원 노드를 제거하여 **대기 그래프(wait-for graph)**를 만든다. Tᵢ→Tⱼ는 Tᵢ가 Tⱼ 소유 자원의 반환을 기다림을 뜻한다. 이 경우 사이클이 있는 것과 교착이 동치이다. 원문은 그래프 사이클 탐지에 O(n²) 연산이 필요하다고 설명한다.'),
 p('여러 인스턴스에서는 Available·Allocation과 현재 요청 행렬 **Request**를 사용한다. 회피의 Need가 미래 최대 추가 요구인 것과 달리 Request는 지금 기다리는 요청이다. Work=Available로 시작하고 Allocation이 0인 스레드는 Finish=true, 나머지는 false로 둔다. 미완료이면서 Requestᵢ≤Work인 스레드를 찾아 Allocationᵢ를 돌려받는다고 가정한다. 더 찾지 못했을 때 Finish=false인 스레드들이 교착에 연루된다. 원문은 m×n² 연산을 명시한다.'),
 fig(c,'여러 인스턴스의 교착 상태 탐지 절차',373,(.17,.481,.913,.81),'8.7.2 원문의 4단계 알고리즘.','현재 Request를 충족한 스레드가 더 요청하지 않고 끝낸다는 낙관적 가정으로 자원을 회수한다. 이 가정이 틀려 이후 교착하면 다음 탐지에서 나타난다는 설명도 원문에 있다.'),
 p('원문의 예에서 A=7, B=2, C=6이고 Available=(0,0,0)이어도 T₀ → T₂ → T₃ → T₁ → T₄로 끝낼 수 있어 교착이 아니다. T₂가 C 하나를 더 요청하면 T₀ 자원을 회수해도 나머지 요청을 충족하지 못하여 T₁·T₂·T₃·T₄가 교착에 연루된다.'),
 p('탐지 빈도는 교착 발생 빈도와 보통 연루되는 스레드 수에 달린다. 즉시 만족되지 않는 요청마다 검사하면 원인 시점을 찾기 쉽지만 비용이 크다. 일정 간격이나 CPU 이용률 하락 때만 검사하면 비용은 줄어도 원인 스레드를 특정하기 어려워진다. 원문의 BCC 도구·Java 스레드 덤프·데이터베이스 예는 모두 대기 관계를 관찰하여 사이클을 찾는 의미로 연결된다. 데이터베이스는 희생 트랜잭션을 중단·rollback하여 락을 풀고 나머지를 재개한다.'))
sec(c,'8.8','교착 상태로부터 회복',376,377,
 p('탐지 후 운영자에게 알려 수동 처리하거나 시스템이 자동으로 회복할 수 있다. 자동 방법은 한 개 이상의 프로세스·스레드를 종료하여 순환 대기를 깨거나 점유 자원을 선점하는 것이다. 모든 교착 프로세스를 한꺼번에 중지하면 확실하지만 이미 수행한 계산을 잃는다. 한 개씩 중지하면 매번 재탐지하는 비용이 든다.'),
 p('종료 대상은 우선순위, 지금까지와 남은 실행 시간, 점유한 자원의 종류·수, 앞으로 필요한 자원, 중지해야 할 프로세스 수 등을 고려한다. 파일 갱신 중 종료하면 파일이 부정확해질 수 있고 락을 풀어도 공유 데이터 무결성이 보장되는 것은 아니다.'),
 table(['선점 시 고려','원문 조건'],[['희생자 선택','점유 자원·실행 시간 등의 비용을 최소화하는 순서를 선택한다.'],['후퇴(rollback)','자원이 없어진 프로세스는 정상 진행할 수 없어 안전한 상태로 되돌린다. 완전 재시작은 간단하지만 필요한 만큼만 후퇴하려면 더 많은 상태 정보를 유지해야 한다.'],['기아 방지','같은 프로세스가 계속 희생되지 않도록 한정된 횟수만 선택되게 해야 한다. 비용에 후퇴 횟수를 포함하는 것이 일반적인 해법이다.']]))
sec(c,'8.9','요약',378,381,p('교착 상태는 네 필요조건·요청과 할당 관계·현재와 미래 요구량을 연결하여 판단한다. 사이클의 의미는 자원 인스턴스 수에 따라 다르며 안전·불안전·교착을 구별한다. 원문 연습 문제는 안전 상태, 은행원 알고리즘, 봉쇄와 자원 순서, 탐지·기아 및 자원 선점 정책을 점검한다. 제공된 문제의 새 풀이를 작성하지 않았다.'))
finish(c,['교착의 네 필요조건은 동시에 성립해야 한다.','자원 할당 그래프의 사이클은 단일 인스턴스에서는 필요충분, 여러 인스턴스에서는 필요조건이다.','불안전과 교착은 같지 않다. 회피는 요청 후 안전 순서를 보존하는지 본다.','은행원의 Need와 탐지의 현재 Request를 구분한다.','탐지만으로 끝나지 않으며 종료·자원 선점·후퇴·기아 대책을 함께 마련해야 한다.'],['요청·사용·방출 → 대기 고리 → 네 조건의 제거 또는 상태 검사로 연결한다.','예방은 요청 규칙, 회피는 미래 최대 요구와 안전성, 탐지는 현재 요청·할당을 사용한다.','교착 복구의 선택은 잃는 계산·자료 무결성·반복 희생의 비용과 연결된다.'],[('교착과 라이브락의 차이를 설명할 수 있는가?',351,354),('사이클과 교착의 관계를 인스턴스 수에 따라 구분할 수 있는가?',355,358),('안전 순서·불안전 상태·교착 상태의 관계를 설명할 수 있는가?',365,366),('은행원 자료구조와 안전성·요청 검사 순서를 설명할 수 있는가?',368,371),('현재 Request를 쓰는 탐지와 Need를 쓰는 회피를 구별할 수 있는가?',368,374),('선점 복구의 희생자·후퇴·기아 문제를 설명할 수 있는가?',376,377)],[('교착 상태','8.1'),('라이브락','8.2'),('자원 할당 그래프','8.3'),('순환 대기','8.5'),('안전 상태','8.6.1'),('은행원 알고리즘','8.6.3'),('대기 그래프','8.7'),('교착 상태 회복','8.8')])

c=chapter(9)
c['overview']=['CPU가 만드는 논리 주소와 실제 메모리의 물리 주소를 연결하는 방법을 메모리 보호·주소 바인딩·MMU의 관점에서 정리한다.','연속 할당과 단편화에서 출발하여 페이징·TLB·페이지 테이블 구조·스와핑으로 확장하고, 원문이 제시한 Intel·ARM 주소 변환 사례를 다룬다.']
c['flow']=['하드웨어와 주소 바인딩 → 논리·물리 주소 → 동적 적재·연결','연속 할당의 배치와 단편화 → 페이지·프레임 변환 → TLB·보호·공유','페이지 테이블 구조 → 스와핑 → IA-32·x86-64·ARMv8 사례']
sec(c,'9.1','배경',385,393,p('다중 프로그래밍으로 CPU 이용률·응답성을 높이려면 여러 프로세스를 메모리에 유지해야 한다. 메모리는 고유 주소를 가진 바이트들의 배열이며 CPU는 명령 인출·해독·피연산자 인출·실행·결과 저장을 수행한다. 메모리는 제시된 주소에 따라 읽고 쓸 뿐 그 주소가 생성된 방식이나 내용의 의미를 알지 못한다. 메모리 관리 방식은 하드웨어 설계와 긴밀하게 연결된다.'))
sec(c,'9.1.1','기본 하드웨어',386,388,
 p('CPU가 직접 접근하는 범용 저장장치는 메인 메모리와 코어 레지스터이다. 명령·데이터가 디스크에 있으면 처리 전 메모리로 옮겨야 한다. 레지스터와 메인 메모리의 접근 속도 차이 때문에 CPU가 데이터 대기 중 stall될 수 있으며 캐시가 이를 완화한다.'),
 p('동시에 운영체제와 다른 사용자 프로세스의 공간을 보호해야 한다. 각 프로세스에 독립된 합법 주소 영역을 정하고 사용자 모드의 모든 주소를 하드웨어가 검사한다. 원문의 **기준(base) 레지스터**는 가장 작은 합법 물리 주소, **상한(limit) 레지스터**는 영역 크기를 저장한다. 기준 이상이며 기준+상한보다 작은 범위인지 검사하는 그림 9.2의 관계가 보호 기준이다. 범위를 벗어나면 운영체제에 트랩한다.'),
 p('두 레지스터는 커널 모드에서만 가능한 특권 명령으로 운영체제만 적재한다. 커널은 사용자 영역과 운영체제 영역을 모두 접근할 수 있어 프로그램 적재, 오류 덤프, 시스템 콜 인수 처리, 문맥 교환 등을 수행한다. 보호 검사를 소프트웨어 호출마다 수행하는 것으로 해석하지 않는다.'))
sec(c,'9.1.2','주소의 할당',388,390,
 p('프로그램은 실행 파일에서 메모리로 적재되어 프로세스 문맥에 배치된다. 주소는 원시 프로그램의 심볼에서 컴파일러가 만드는 재배치 가능 주소, 링커·로더가 만드는 절대 주소로 바뀔 수 있다. 각 바인딩은 한 주소 공간을 다른 주소 공간에 사상한다.'),
 table(['시점','조건과 결과'],[['컴파일 시간','적재 위치를 미리 알면 절대 코드를 만든다. 시작 위치를 변경하려면 다시 컴파일한다.'],['적재 시간','컴파일 때 위치를 모르면 재배치 가능 코드를 만든다. 실제 적재 시 바인딩하며 시작 위치가 바뀌면 다시 적재한다.'],['실행 시간','실행 중 다른 메모리 위치로 이동할 수 있도록 바인딩을 실행까지 미룬다. 특별한 하드웨어 지원이 필요하다.']]))
sec(c,'9.1.3','논리 대 물리 주소 공간',390,391,
 p('**논리 주소**는 CPU가 생성하는 주소이고 **물리 주소**는 메모리 주소 레지스터에 제시되어 메모리가 취급하는 주소이다. 컴파일·적재 시간 바인딩에서는 두 주소가 같지만 실행 시간 바인딩에서는 다르다. 이 책은 논리 주소와 가상 주소를 같은 뜻으로 사용한다.'),
 p('**메모리 관리 장치(MMU)**는 실행 중 논리 주소를 물리 주소로 바꾼다. 단순한 동적 재배치에서는 재배치 레지스터 값을 모든 논리 주소에 더한다. 원문의 값 14000과 논리 주소 346은 물리 주소 14346으로 연결된다. 사용자 프로그램은 논리 주소를 생성·저장·비교할 수 있지만 실제 메모리 참조 때 하드웨어가 바인딩하므로 실제 물리 위치를 직접 접근하는 것으로 이해하면 안 된다.'))
sec(c,'9.1.4','동적 적재',391,392,
 p('**동적 적재(dynamic loading)**는 루틴을 실제로 호출할 때까지 메모리에 올리지 않는다. 루틴은 디스크에 재배치 가능 형태로 대기하고 main이 실행되다가 다른 루틴을 부르면 이미 적재됐는지 조사한다. 없으면 연결 적재기가 가져오고 테이블을 갱신한 뒤 제어를 넘긴다. 오류 처리처럼 실행 빈도가 낮고 큰 루틴에 유리하다. 원문은 운영체제의 특별한 지원 없이 프로그램 설계로 가능하고 구현 라이브러리를 제공받을 수 있다고 설명한다.'))
sec(c,'9.1.5','동적 연결 및 공유 라이브러리',392,393,
 p('**동적 연결**은 적재 자체를 미루는 동적 적재와 달리 라이브러리 연결을 실행 시점까지 미룬다. 정적 연결은 참조 라이브러리를 각 실행 이미지에 포함하지만 DLL은 실행할 때 찾아 주소를 조정한다. 여러 프로세스가 하나의 물리 사본을 공유할 수 있어 실행 이미지·메모리 공간을 줄인다.'),
 p('라이브러리 갱신 뒤 새 버전을 쓰려면 정적 연결은 재연결이 필요하지만 동적 연결은 새 버전을 사용할 수 있다. 단, 여러 버전이 공존할 수 있으므로 프로그램·라이브러리에 버전 정보를 두어 원하는 버전을 구별한다. 동적 연결·공유에는 일반적으로 운영체제 지원이 필요하며 각자의 공간이 보호된 프로세스들이 같은 메모리를 이용할 수 있게 해야 한다.'))
sec(c,'9.2','연속 메모리 할당',393,397,
 p('메모리는 운영체제 영역과 사용자 영역으로 나뉘며 연속 할당은 각 프로세스에 하나의 연속된 영역을 준다. 재배치 레지스터는 가장 작은 물리 주소, 상한 레지스터는 논리 주소 범위를 유지한다. MMU는 논리 주소가 범위 안인지 확인하고 재배치 값을 더한다. 디스패처는 문맥 교환 때 두 값을 적재한다.'),
 p('가변 크기 파티션은 각각 프로세스 하나를 담는다. 운영체제는 사용 중·가용 영역을 기록한다. 프로세스 종료로 생긴 **hole**을 다시 할당하며 요청보다 크면 분할하고 반환 영역이 인접 hole과 붙으면 병합한다. 공간이 부족하면 거부하거나 대기 큐에 둘 수 있다.'),
 table(['전략','선택 기준·검색'],[['최초 적합','충분히 큰 첫 공간을 고른다. 시작 또는 지난 검색 위치부터 찾고 발견하면 끝낸다.'],['최적 적합','요청을 만족하는 가장 작은 공간을 고른다. 크기순이 아니면 전체를 검색하며 작은 나머지를 남긴다.'],['최악 적합','가장 큰 공간을 고른다. 남은 공간도 다른 용도로 충분히 클 것을 기대한다. 크기순이 아니면 전체 검색이 필요하다.']]),
 p('원문 모의실험 설명에서는 최초·최적 적합이 시간·공간 효율에서 최악 적합보다 좋다. 최초와 최적 중 공간 효율이 항상 우세한 것은 없지만 최초가 일반적으로 빠르다. 이는 이름의 최적을 모든 조건의 최적 성능이라고 해석하지 않아야 하는 이유이다.'),
 table(['단편화','발생 위치·조건'],[['외부 단편화','가용 공간 총합은 충분해도 작은 비연속 조각으로 나뉘어 요청을 만족하지 못한다.'],['내부 단편화','할당 단위 때문에 실제 요청보다 큰 영역을 주어 할당 내부의 일부를 쓰지 못한다.']]),
 p('원문은 최초 적합에서 N개 할당 블록에 대해 0.5N개 블록이 단편화로 손실될 수 있는 **50% 규칙**을 설명한다. 외부 단편화의 **압축(compaction)**은 사용 내용을 한쪽으로 모아 큰 가용 영역을 만든다. 실행 시간의 동적 재배치가 있어야 가능하며 정적 바인딩에서는 할 수 없고 이동 비용도 크다. 논리 공간을 비연속 물리 영역에 놓는 페이징은 다른 해결 방향이다.'))
sec(c,'9.3','페이징',397,408,p('**프레임**은 물리 메모리의 고정 크기 블록, **페이지**는 논리 메모리의 같은 크기 블록이다. 페이지를 가용 프레임에 놓으면 프로세스 물리 공간이 연속일 필요가 없어 외부 단편화와 그 압축을 피한다. 논리 주소 공간 크기와 물리 메모리 용량을 분리하며 운영체제·하드웨어가 협력하여 구현한다.'))
sec(c,'9.3.1','기본 방법',397,402,
 p('논리 주소는 페이지 번호 p와 페이지 오프셋 d로 나뉜다. 페이지 번호가 프로세스별 페이지 테이블의 인덱스이며 테이블에서 찾은 프레임 번호 f와 원래 오프셋으로 물리 주소를 만든다. 오프셋은 변하지 않는다.'),
 steps('MMU의 주소 변환','논리 주소에서 p를 추출한다.','페이지 테이블에서 p에 대응하는 f를 얻는다.','p를 f로 바꾸고 d는 유지하여 물리 주소를 만든다.'),
 formula('논리 주소 공간 2^m, 페이지 크기 2^n 바이트 → 상위 m−n비트: p / 하위 n비트: d',['m: 논리 주소의 비트 수','n: 페이지 안 오프셋의 비트 수'],'페이지 크기는 하드웨어가 정하며 2의 거듭제곱이므로 비트로 나누어 변환할 수 있다.'),
 fig(c,'페이징 하드웨어의 페이지·프레임 변환',398,(.18,.642,.90,.942),'그림 9.8. 원문 그림.','p로 프레임 f를 찾고 d를 그대로 유지하는 주소 변환을 보여준다.'),
 p('원문의 4 B 페이지·32 B 물리 메모리 예에서 페이지 테이블은 페이지 0→프레임 5, 1→6, 2→1, 3→2이다. 논리 주소 0은 20, 3은 23, 4는 24, 13은 9로 사상된다. 이들은 원문에 명시된 결과이다. 프레임 단위로 할당하므로 외부 단편화는 없지만 마지막 페이지의 **내부 단편화**는 남는다.'),
 p('원문 예에서 2,048 B 페이지와 72,766 B 요구는 마지막 페이지에 1,086 B를 사용하여 962 B를 낭비한다. 크기와 페이지 크기가 무관하면 평균적으로 반 페이지의 내부 단편화가 예상된다. 작은 페이지는 이를 줄이지만 페이지 테이블을 키우며 큰 페이지는 디스크 효율에 유리하다는 절충이 있다.'),
 p('운영체제는 가용 프레임을 배정하고 페이지를 적재하여 테이블을 채운다. 프로그래머에게는 자기만의 연속 공간처럼 보이지만 실제 프로그램은 여러 프레임에 분산되고 다른 프로세스와 공존한다. 시스템의 **프레임 테이블**은 프레임별 가용 여부·소유 프로세스·페이지를 기록한다. 운영체제는 사용자 인수 주소를 변환하고 문맥 교환 때 테이블을 설정해야 하므로 페이징은 문맥 교환 비용도 늘린다.'))
sec(c,'9.3.2','하드웨어 지원과 TLB',402,406,
 p('작은 페이지 테이블은 전용 레지스터로 구현할 수 있지만 각 문맥 교환에서 여러 값을 바꿔야 한다. 큰 테이블은 메인 메모리에 두고 **페이지 테이블 기준 레지스터(PTBR)**가 가리키게 하면 프로세스 변경 때 PTBR만 바꾸면 된다. 그러나 데이터를 얻기 위해 테이블과 실제 데이터에 두 번 접근하는 지연이 생긴다.'),
 p('**TLB(translation look-aside buffer)**는 페이지 테이블 일부를 보관하는 매우 빠른 연관 메모리이다. 페이지 번호를 여러 키와 동시에 비교하여 프레임 번호를 얻는다. 맞으면 즉시 변환하고, 없으면 테이블을 읽어 변환한 뒤 TLB에 추가한다. 가득 차면 LRU·라운드 로빈·무작위 등 정책으로 바꾸며 중요한 커널 항목을 고정할 수 있다.'),
 p('각 TLB 항목의 **ASID(address-space identifier)**는 어느 프로세스의 주소 공간인지 식별한다. 현재 프로세스와 다르면 미스로 처리하여 다른 프로세스 정보가 잘못 사용되는 것을 막는다. ASID가 있으면 여러 프로세스 항목을 함께 보관하고, 없으면 새 테이블 선택 때 TLB를 flush해야 한다.'),
 p('**적중률(hit ratio)**은 원하는 페이지 번호가 TLB에서 발견되는 비율이다. 원문의 계산식은 메모리 접근 10 ns, 테이블 미스의 두 번 접근 20 ns를 사용하여 80% 적중 때 12 ns, 99% 때 10.1 ns를 얻는다. 단일 테이블 접근을 가정한 예이며 여러 TLB 계층·여러 테이블 접근이면 추가 정보가 필요하다.'),
 fig(c,'원문의 TLB 실질 접근 시간 계산',405,(.35,.43,.72,.588),'인쇄405쪽의 두 계산식.','0.80×10+0.20×20=12 ns, 0.99×10+0.01×20=10.1 ns라는 원문 식을 보존하였다.'),
 p('**원문 확인 필요:** 같은 쪽의 앞 설명 문장에는 TLB 적중 시 "100 ns"가 기재되어 있으나 뒤의 식과 비교 설명은 "10 ns"를 사용한다. 이를 조용히 수정하지 않고 원문 내부 표기 불일치로 남긴다. 다단계 TLB의 일반 효과만 취하며 다른 수치를 새로 계산하지 않았다.'))
sec(c,'9.3.3','보호',406,407,
 p('페이지 테이블의 **보호 비트**는 읽기·쓰기 또는 읽기 전용 같은 접근 권한을 지정한다. 주소 변환과 함께 검사하여 읽기 전용에 쓰면 보호 위반 트랩을 낸다. **유효/무효 비트**는 그 페이지가 프로세스의 합법 논리 주소 공간에 속하는지 나타내며 접근 허용 여부를 결정한다.'),
 p('페이지 단위 보호는 마지막 페이지 안에서 실제 사용 범위보다 넓은 주소를 유효하게 둘 수 있다. 원문의 14비트 주소·2 KB 페이지 예에서 프로그램은 10,468까지 쓰지만 페이지 5 전체가 유효하여 12,287까지 유효로 취급된다. 이는 내부 단편화와 연결된다. 테이블 크기를 나타내는 **PTLR(page table length register)**로 유효 테이블 범위를 확인하는 방법도 제시된다.'))
sec(c,'9.3.4','공유 페이지',407,408,
 p('공통 코드는 **재진입 코드**, 즉 실행 중 자체 수정이 없는 코드이면 여러 프로세스가 동시에 공유할 수 있다. 각 프로세스는 레지스터·데이터 저장영역을 따로 가지며 같은 물리 코드 사본을 각자의 테이블에 매핑한다. 원문의 libc=2 MB·40프로세스 예는 각각 복사할 때 80 MB 대신 공유 사본 2 MB가 필요하다고 비교한다.'),
 p('읽기 전용 속성은 코드 정확성에만 맡기지 않고 운영체제가 강제해야 한다. 공유 라이브러리뿐 아니라 프로세스 간 공유 메모리 통신도 같은 프레임에 여러 테이블을 연결하는 방식으로 구현될 수 있다. 프로세스 간 공유가 각자의 데이터까지 모두 같은 것으로 만든다는 뜻은 아니다.'))
sec(c,'9.4','페이지 테이블의 구조',409,414,
 p('주소 공간이 커지면 페이지 테이블 자체의 물리 메모리 비용이 커진다. 원문은 계층적·해시·역 페이지 테이블과 SPARC Solaris 사례로 테이블 저장·탐색의 절충을 설명한다.'))
sec(c,'9.4.1','계층적 페이징',409,411,
 p('32비트 주소·4 KB 페이지·4 B 항목 예는 페이지 테이블만 프로세스당 4 MB를 요구한다. 테이블을 연속 공간에 두는 대신 **테이블 자체를 페이징**한다. 2단계에서는 20비트 페이지 번호를 바깥 인덱스 10비트와 안쪽 인덱스 10비트로, 오프셋은 12비트로 나눈다. 바깥에서 안쪽으로 변환하므로 forward-mapped라고도 부른다.'),
 p('원문의 완전한 64비트 공간·4 KB 가정은 2단계로도 바깥 테이블이 지나치게 커지고 단계를 계속 늘리면 변환의 메모리 접근이 많아지는 문제를 보인다. 이는 다음 해시·역 테이블의 동기이다. 이 예의 전체 64비트 가정과 뒤에서 설명하는 실제 48비트 주소 사용 사례를 혼동하지 않는다.'))
sec(c,'9.4.2','해시 페이지 테이블',411,412,
 p('큰 주소 공간에서 가상 페이지 번호를 해시한 위치에 연결 리스트를 둔다. 원소는 가상 페이지 번호·프레임 번호·다음 원소 포인터를 가진다. 해시 충돌 리스트를 따라 원하는 가상 페이지 번호와 일치하는 항목을 찾아 물리 프레임을 얻는다. **클러스터 페이지 테이블**은 한 항목이 한 페이지가 아니라 여러 페이지를 가리켜 넓게 퍼진 성긴 주소 공간에 유용하다.'))
sec(c,'9.4.3','역 페이지 테이블',412,413,
 p('일반 테이블은 프로세스별 가상 페이지마다 항목을 가지지만 **역 페이지 테이블**은 시스템 전체에서 물리 프레임마다 하나의 항목을 둔다. 항목은 그 프레임의 페이지 주소와 소유 프로세스 ID를 기록한다. 원문 IBM RT 설명에서는 <process-id, page-number>를 검색하여 i번째 항목에서 찾으면 물리 주소는 <i, offset>이 된다.'),
 p('물리 메모리 기준 항목만 유지하여 공간이 줄지만 가상 주소로 테이블 전체를 찾는 데 시간이 오래 걸릴 수 있다. 해시로 탐색을 줄이고 먼저 TLB를 확인하여 성능을 보완한다. 프레임당 항목 하나라 같은 물리 페이지를 여러 가상 주소로 동시에 나타내는 공유 메모리가 복잡해진다. 원문은 다른 프로세스가 참조하면 페이지 폴트와 매핑 변경을 거치는 방식의 한계를 설명한다.'))
sec(c,'9.4.4','Oracle SPARC Solaris',414,414,
 steps('원문의 변환 단계','하드웨어가 TLB에서 변환 테이블 항목(TTE)을 찾는다.','없으면 메모리의 변환 저장 버퍼(TSB)에서 최근 TTE를 찾고 TLB로 복사한다.','TSB에도 없으면 인터럽트하여 커널이 해시 테이블을 탐색한다.','커널이 TTE를 만들어 TSB에 넣고 MMU에 제어를 돌려 변환을 끝낸다.'),
 p('커널과 사용자 프로세스용 해시 테이블은 각 항목이 연속 가상 영역의 기준 주소와 범위를 나타내어 페이지마다 항목을 두는 비용을 줄인다. 하드웨어·운영체제가 함께 다단계 탐색을 줄이는 원문 사례로 읽는다.'))
sec(c,'9.5','스와핑',414,417,
 p('**스와핑**은 프로세스나 일부를 메모리에서 백업 저장장치로 내보냈다가 실행을 계속하려고 가져오는 기법이다. 물리 메모리보다 프로세스 총 공간이 커도 동시에 유지할 수 있어 다중 프로그래밍 정도를 높인다. 전체 프로세스의 표준 스와핑은 이미지뿐 아니라 복원할 자료구조·다중 스레드별 정보·메타데이터도 보존해야 한다.'),
 table(['방식','원문 의미와 조건'],[['표준 스와핑','전체 프로세스를 이동한다. 유휴 프로세스 메모리를 활성 프로세스에 줄 수 있지만 큰 이동 비용이 든다. 원문은 현대 시스템에서 드물고 Solaris의 극한 부족 상황을 예외로 든다.'],['페이징에서의 스와핑','프로세스의 일부 페이지만 page-out·page-in하여 전체 복사 비용을 줄인다.'],['모바일 시스템','원문은 일반적으로 스와핑을 피한다고 설명한다. 플래시 공간·쓰기 횟수·낮은 처리량 제약 때문이다.']]),
 p('원문의 iOS는 부족하면 응용이 메모리를 자발적으로 반환하게 하고 읽기 전용 코드는 제거 후 다시 읽을 수 있지만 수정한 데이터는 그렇게 제거하지 못한다. 충분히 반환하지 못하면 종료될 수 있다. Android는 비슷하게 프로세스를 종료하되 상태를 플래시에 저장하여 재시작을 돕는다. 이는 제공된 원문의 서술이며 현재 제품 동작으로 확대하지 않는다.'))
sec(c,'9.6','사례: Intel 32비트와 64비트 구조',417,421,
 p('IA-32의 변환은 **논리 주소 → 세그먼테이션 장치 → 선형 주소 → 페이징 장치 → 물리 주소**이다. 두 장치가 MMU 역할을 나눈다. 세그먼트 디스크립터는 기준·상한 정보를 가지며 프로세스별 LDT와 공유 GDT를 구분한다. 논리 주소의 selector가 테이블·세그먼트·보호 정보를 선택하고 offset을 검사한 뒤 기준에 더해 32비트 선형 주소를 만든다.'),
 p('IA-32의 4 KB 페이지는 2단계 페이징이다. 상위 10비트가 CR3이 가리키는 페이지 디렉터리, 다음 10비트가 페이지 테이블, 마지막 12비트가 오프셋이다. 페이지 디렉터리의 Page Size 플래그가 4 MB를 지정하면 하위 테이블 대신 프레임을 직접 가리키고 하위 22비트를 오프셋으로 쓴다. 디스크의 페이지 테이블은 invalid 비트를 이용해 나중에 가져올 수 있다.'),
 p('**PAE(page address extension)**는 원문에서 32비트 처리기의 물리 공간을 확장하는 3단계 테이블로 설명된다. 최상위 2비트가 페이지 디렉터리 포인터 테이블을 선택하고 항목을 64비트로 늘려 12비트 오프셋과 합한 36비트 물리 주소·64 GB를 지원한다. 사용하려면 운영체제 지원이 필요하며 원문은 32비트 Windows 데스크톱의 4 GB 제한도 별도 언급한다.'),
 p('원문의 **x86-64**는 IA-32 명령 집합 확장에서 출발하며 이론적 64비트 전체와 실제 사용 비트 수를 구분한다. 제시된 구조는 48비트 가상 주소·4단계 테이블·4 KB/2 MB/1 GB 페이지와 52비트 물리 주소를 지원한다. 이 수치는 제공된 책의 설명으로 한정한다.'),
 fig(c,'x86-64 선형 주소의 원문 필드',421,(.17,.101,.90,.19),'그림 9.25. 원문 주소 구조.','47~39, 38~30, 29~21, 20~12의 계층 인덱스와 11~0 오프셋을 구분한다.'))
sec(c,'9.7','사례: ARM 구조',421,423,
 p('원문은 64비트 **ARMv8**를 대상으로 설명하며 실제 사용 가상 주소는 48비트라고 구분한다. 4 KB·16 KB·64 KB의 변환 단위가 있고 페이지뿐 아니라 더 큰 연속 영역 region을 표현한다. 4 KB·16 KB는 최대 4단계, 64 KB는 최대 3단계 페이징을 사용할 수 있다.'),
 table(['변환 단위','페이지','Region'],[['4 KB','4 KB','2 MB, 1 GB'],['16 KB','16 KB','32 MB'],['64 KB','64 KB','512 MB']]),
 p('4 KB 예에서는 TTBR이 레벨0 테이블을 가리킨다. 레벨1이 1 GB region을 직접 가리키면 하위 30비트, 레벨2가 2 MB region을 직접 가리키면 하위 21비트가 오프셋이다. 네 단계 모두 사용하면 마지막 12비트가 4 KB 페이지 안 오프셋이다. 구조의 다른 레벨·영역을 임의로 덧붙이지 않는다.'),
 p('ARM TLB는 명령·데이터용 마이크로 TLB와 바깥 단일 메인 TLB로 나뉜다. 마이크로 TLB는 ASID를 지원한다. 먼저 마이크로, 다음 메인 TLB를 찾고 둘 다 미스이면 하드웨어가 테이블을 순회한다.'))
sec(c,'9.8','요약',423,426,p('주소 생성·보호·사상은 하드웨어와 운영체제의 협력으로 이루어진다. 연속 할당의 외부 단편화를 페이징으로 피하지만 내부 단편화·테이블·변환 비용은 남는다. TLB와 여러 테이블 구조는 그 비용을 조절한다. 원문 연습 문제는 단편화 구분, 주소의 비트 수, 페이지·오프셋, 배치 전략, 일반·역 테이블 항목 수 등을 확인한다. 새 계산 문제나 답을 만들지 않았다.'))
c['limitations']=['인쇄405쪽(PDF345쪽) TLB 적중 시간의 본문 100 ns와 식의 10 ns가 일치하지 않아 원문 확인 필요로 표시하였다.']
finish(c,['논리 주소는 CPU가 생성하며 MMU가 물리 주소로 변환한다.','바인딩 시점과 실행 중 재배치 가능 여부를 연결한다.','페이지 번호만 프레임 번호로 바뀌고 오프셋은 유지된다.','PTBR·TLB·ASID·보호 비트·유효 비트의 역할을 구분한다.','페이지 테이블 구조는 저장 공간·탐색 비용·공유 방식의 절충이다.','제품·구조별 지원 수치는 원문의 시점과 범위로 읽는다.'],['프로세스별 주소 공간 → 하드웨어 보호 → 바인딩·MMU 변환의 관계를 연결한다.','연속 공간의 단편화 → 비연속 프레임 할당 → 페이지 테이블 → TLB의 흐름으로 복습한다.','전체 주소 비트 수·실제 사용하는 비트·페이지 크기·단계 수를 서로 다른 기준으로 구분한다.'],[('컴파일·적재·실행 시간 바인딩과 재배치 조건을 설명할 수 있는가?',388,391),('동적 적재와 동적 연결의 차이를 설명할 수 있는가?',391,393),('최초·최적·최악 적합과 내부·외부 단편화를 구분할 수 있는가?',394,397),('페이지 번호·프레임 번호·오프셋을 원문 예에 연결할 수 있는가?',397,400),('TLB 미스와 ASID·flush·보호 비트의 역할을 설명할 수 있는가?',403,407),('계층적·해시·역 테이블의 구조 차이를 설명할 수 있는가?',409,414),('IA-32·x86-64·ARMv8의 원문 변환 흐름을 구분할 수 있는가?',417,423)],[('주소 바인딩','9.1.2'),('MMU','9.1.3'),('동적 적재','9.1.4'),('동적 연결','9.1.5'),('외부 단편화','9.2'),('내부 단편화','9.2'),('페이징','9.3'),('TLB','9.3.2'),('ASID','9.3.2'),('역 페이지 테이블','9.4.3'),('스와핑','9.5'),('PAE','9.6'),('ARMv8','9.7')])
